#!/bin/bash
# 28_music_rank_capsule.sh
# v5 2026-10-16: 浅绿胶囊 + 音质纯文字标签(SQ/HQ/Hi-Res, Bold) + V2->V3 接线
set -e
cd "$(dirname "$0")/../.." 2>/dev/null || true
BASE="avbox"
RANK_KT="$BASE/app/src/main/java/com/github/tvbox/osc/ui/music/rank/RankScreen.kt"

if [ -f "$RANK_KT" ] && grep -q "FontWeight.Bold" "$RANK_KT" 2>/dev/null; then
  echo "skip rank"
else
  mkdir -p "$(dirname "$RANK_KT")"
  echo "" | base64 -d > "$RANK_KT"
  echo "rank written"
fi

TARGET="$BASE/app/src/main/java/com/github/tvbox/osc/ui/activity/MusicHomeActivity.kt"
if [ ! -f "$TARGET" ]; then
  echo "FATAL: no target"; exit 1
fi

python3 - "$TARGET" <<'PYEOF2'
import sys
path = sys.argv[1]
src = open(path, encoding='utf-8').read()
MARK3 = '// NAV_WIRE_V3'
if MARK3 in src:
    print("V3 done"); sys.exit(0)
old_full = 'hasSQ = it.quality.isNotBlank(), // NAV_WIRE_V2: 真实音质（SQ/HQ/24bit）才显示'
assert src.count(old_full) == 1, "anchor fail"
new_block = '''qualityLabel = when (it.quality) { // NAV_WIRE_V3
                    "24bit" -> "Hi-Res"
                    "SQ" -> "SQ"
                    "HQ" -> "HQ"
                    else -> ""
                },'''
src = src.replace(old_full, new_block)
open(path, 'w', encoding='utf-8').write(src)
print("V3 OK")
PYEOF2

echo "28 done"
